import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const HOME = path.join(ROOT, 'data', 'home');
const NODE_ROOT = path.join(ROOT, 'runtime', 'node');
const dryRun = !process.argv.includes('--apply');
const trimRuntime = process.argv.includes('--trim-runtime');

// These locations are generated by the browser/npm/runtime and can be rebuilt.
// Transcript files, auth.db, browser profile preferences and project workspaces
// are deliberately outside this list.
const cacheDirectories = [
  path.join(HOME, '.npm-cache'),
  path.join(HOME, 'temp'),
  path.join(HOME, 'AppData', 'Local', 'Microsoft', 'Edge', 'User Data', 'Default', 'Cache'),
  path.join(HOME, 'AppData', 'Local', 'Microsoft', 'Edge', 'User Data', 'Default', 'Code Cache'),
  path.join(HOME, 'AppData', 'Local', 'Microsoft', 'Edge', 'User Data', 'Default', 'GPUCache'),
  path.join(HOME, 'AppData', 'Local', 'Microsoft', 'Edge', 'User Data', 'Default', 'Service Worker', 'CacheStorage'),
  path.join(HOME, 'AppData', 'Local', 'Microsoft', 'Edge', 'User Data', 'component_crx_cache'),
];

function byteCount(target) {
  if (!fs.existsSync(target)) return 0;
  try {
    if (fs.statSync(target).isFile()) return fs.statSync(target).size;
  } catch { return 0; }
  let total = 0;
  const stack = [target];
  while (stack.length) {
    const current = stack.pop();
    let entries;
    try { entries = fs.readdirSync(current, { withFileTypes: true }); } catch { continue; }
    for (const entry of entries) {
      const item = path.join(current, entry.name);
      if (entry.isDirectory()) stack.push(item);
      else {
        try { total += fs.statSync(item).size; } catch { /* transient cache file */ }
      }
    }
  }
  return total;
}

function removeContents(directory) {
  if (!fs.existsSync(directory)) return 0;
  let removed = 0;
  for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
    const target = path.join(directory, entry.name);
    removed += byteCount(target);
    if (!dryRun) {
      try { fs.rmSync(target, { recursive: true, force: true }); } catch { /* locked cache files are skipped */ }
    }
  }
  return removed;
}

function findRuntimeMaps() {
  const found = [];
  const stack = [NODE_ROOT];
  while (stack.length) {
    const current = stack.pop();
    let entries;
    try { entries = fs.readdirSync(current, { withFileTypes: true }); } catch { continue; }
    for (const entry of entries) {
      const item = path.join(current, entry.name);
      if (entry.isDirectory()) stack.push(item);
      else if (entry.name.endsWith('.map')) found.push(item);
    }
  }
  return found;
}

function removeRuntimeMaps() {
  let removed = 0;
  for (const file of findRuntimeMaps()) {
    try { removed += fs.statSync(file).size; } catch { continue; }
    if (!dryRun) {
      try { fs.rmSync(file, { force: true }); } catch { /* locked files are skipped */ }
    }
  }
  return removed;
}

const before = cacheDirectories.reduce((sum, directory) => sum + byteCount(directory), 0);
let reclaimable = cacheDirectories.reduce((sum, directory) => sum + removeContents(directory), 0);
if (trimRuntime) reclaimable += removeRuntimeMaps();
const after = dryRun ? before - reclaimable : cacheDirectories.reduce((sum, directory) => sum + byteCount(directory), 0);

console.log(`[portable-prune] mode=${dryRun ? 'dry-run' : 'apply'} cache-before=${(before / 1024 / 1024).toFixed(1)}MB`);
console.log(`[portable-prune] reclaimable=${(reclaimable / 1024 / 1024).toFixed(1)}MB${trimRuntime ? ' (including runtime source maps)' : ''}`);
if (!dryRun) console.log(`[portable-prune] cache-after=${(after / 1024 / 1024).toFixed(1)}MB`);
if (dryRun) console.log('[portable-prune] 未修改文件；确认后运行 node tools/prune-portable-cache.mjs --apply');
